const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;

let keywords = [];
if (Array.isArray(body.keywords)) {
  keywords = body.keywords.map(k => String(k).trim()).filter(Boolean);
} else if (typeof body.keyword === 'string' && body.keyword.trim()) {
  keywords = [body.keyword.trim()];
} else if (typeof body.keywords === 'string') {
  keywords = body.keywords.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
}

keywords = [...new Set(keywords)];

if (keywords.length === 0) throw new Error('No keywords provided.');
if (keywords.length > 25) throw new Error('Maximum 25 keywords per batch (received ' + keywords.length + ').');

return [{
  json: {
    keywords,
    location: String(body.location || 'United States').trim(),
    language: String(body.language || 'en').trim(),
    device: String(body.device || 'desktop').trim(),
    industry: String(body.industry || '').trim(),
    requested_at: body.requested_at || new Date().toISOString()
  }
}];

const input = $input.first().json;
const tasks = input.keywords.map(kw => ({
  keyword: kw,
  location_name: input.location,
  language_code: input.language,
  device: input.device,
  depth: 20
}));
return [{ json: { ...input, dfs_body: tasks } }];

const inputs = $('Normalize Input').first().json;
const serpResp = $input.first().json;
return [{
  json: {
    serp_response: serpResp,
    kd_body: [{
      keywords: inputs.keywords,
      location_name: inputs.location,
      language_code: inputs.language
    }]
  }
}];

const inputs = $('Normalize Input').first().json;
const serpResp = $('DataForSEO SERP (batch)').first().json;
const kdResp = $input.first().json;
const tasks = (serpResp.tasks || []);

// Build KD lookup map (keyword -> 0-100 score)
const kdMap = new Map();
const kdItems = kdResp && kdResp.tasks && kdResp.tasks[0] && kdResp.tasks[0].result && kdResp.tasks[0].result[0] && kdResp.tasks[0].result[0].items;
if (Array.isArray(kdItems)) {
  for (const it of kdItems) {
    if (it && it.keyword) {
      const kd = typeof it.keyword_difficulty === 'number' ? it.keyword_difficulty : null;
      kdMap.set(String(it.keyword).toLowerCase(), kd);
    }
  }
}

function difficultyBand(kd) {
  if (kd == null || Number.isNaN(kd)) return null;
  if (kd < 15) return 'Very Easy';
  if (kd < 30) return 'Easy';
  if (kd < 50) return 'Medium';
  if (kd < 70) return 'Hard';
  if (kd < 85) return 'Very Hard';
  return 'Super Hard';
}

function classifyModifiers(kw) {
  const k = kw.toLowerCase();
  const signals = { transactional: 0, commercial: 0, informational: 0, navigational: 0, local: 0 };
  const hits = [];
  if (/\b(buy|purchase|order|book|schedule|hire|download|subscribe|sign[\s-]?up)\b/.test(k)) { signals.transactional += 3; hits.push('transactional verb'); }
  if (/\b(discount|coupon|deal|promo|price|pricing|cost|cheap|free trial)\b/.test(k)) { signals.transactional += 2; hits.push('price/discount modifier'); }
  if (/\b(best|top|vs|versus|review|reviews|compare|comparison|alternative|alternatives)\b/.test(k)) { signals.commercial += 3; hits.push('comparison/review modifier'); }
  if (/\b(pros and cons|worth it|good for|recommended)\b/.test(k)) { signals.commercial += 2; hits.push('evaluation phrase'); }
  if (/^(what|how|why|when|who|which|where|are|is|does|do|can|should)\b/.test(k)) { signals.informational += 3; hits.push('question starter'); }
  if (/\b(guide|tutorial|how to|tips|learn|examples|definition|meaning|ideas|template)\b/.test(k)) { signals.informational += 2; hits.push('learning modifier'); }
  if (/\b(login|sign in|dashboard|contact|support)\b/.test(k)) { signals.navigational += 2; hits.push('navigational modifier'); }
  if (/\bnear\s?me\b/.test(k)) { signals.local += 4; hits.push('\"near me\"'); }
  const ranked = Object.entries(signals).sort((a, b) => b[1] - a[1]);
  return { signals, top_label: ranked[0][1] > 0 ? ranked[0][0] : null, top_score: ranked[0][1], hits };
}

function pruneSerp(taskResult) {
  if (!taskResult) return null;
  const items = (taskResult.items || []);
  const organic = items.filter(i => i.type === 'organic').slice(0, 10).map(r => ({
    position: r.rank_absolute,
    title: r.title,
    url: r.url,
    description: r.description,
    domain: r.domain
  }));
  const featured = items.find(i => i.type === 'featured_snippet') || null;
  const answerBox = items.find(i => i.type === 'answer_box') || null;
  const knowledgeGraph = items.find(i => i.type === 'knowledge_graph') || null;
  const aiOverview = items.find(i => i.type === 'ai_overview') || null;
  const paaItem = items.find(i => i.type === 'people_also_ask');
  const paa = paaItem ? (paaItem.items || []).slice(0, 6).map(q => q.title).filter(Boolean) : [];
  const relatedItem = items.find(i => i.type === 'related_searches');
  const related = relatedItem ? (relatedItem.items || []).slice(0, 8) : [];
  const localPack = items.filter(i => i.type === 'local_pack').slice(0, 3).map(p => ({ title: p.title, rating: p.rating && p.rating.value }));
  const videoCarousel = items.find(i => i.type === 'video') || items.find(i => i.type === 'videos');
  const shopping = items.find(i => i.type === 'shopping');
  const imagePack = items.find(i => i.type === 'images');
  const feature_presence = {
    featured_snippet: !!featured,
    answer_box: !!answerBox,
    knowledge_graph: !!knowledgeGraph,
    ai_overview: !!aiOverview,
    people_also_ask: paa.length > 0,
    local_pack: localPack.length > 0,
    video_carousel: !!videoCarousel,
    shopping_pack: !!shopping,
    image_pack: !!imagePack
  };
  return {
    organic,
    featured_snippet: featured ? { title: featured.title, description: featured.description } : null,
    knowledge_graph: knowledgeGraph ? { title: knowledgeGraph.title, description: knowledgeGraph.description } : null,
    ai_overview: aiOverview ? { text: aiOverview.text } : null,
    people_also_ask: paa,
    related_searches: related,
    local_pack: localPack,
    feature_presence,
    all_item_types: [...new Set(items.map(i => i.type))]
  };
}

const out = [];
for (let i = 0; i < inputs.keywords.length; i++) {
  const kw = inputs.keywords[i];
  const taskResult = tasks[i] && tasks[i].result && tasks[i].result[0];
  const modifier = classifyModifiers(kw);
  const serp = pruneSerp(taskResult);
  const kd = kdMap.get(String(kw).toLowerCase());
  out.push({
    json: {
      keyword: kw,
      location: inputs.location,
      language: inputs.language,
      device: inputs.device,
      industry: inputs.industry,
      modifier,
      serp,
      serp_missing: !serp,
      keyword_difficulty: typeof kd === 'number' ? kd : null,
      difficulty_band: typeof kd === 'number' ? difficultyBand(kd) : null
    }
  });
}
return out;

const item = $input.first().json;
const targets = item.serp && Array.isArray(item.serp.organic)
  ? item.serp.organic.map(r => r.url).filter(Boolean).slice(0, 10)
  : [];
return [{
  json: {
    ...item,
    bl_body: [{ targets }],
    bl_target_count: targets.length
  }
}];

const upstream = $('Build Backlinks Request').first().json;
const blResp = $input.first().json;
const serp = upstream.serp;
const targetCount = upstream.bl_target_count;

function median(nums) {
  const arr = nums.filter(n => typeof n === 'number' && !Number.isNaN(n)).slice().sort((a, b) => a - b);
  if (!arr.length) return null;
  const mid = Math.floor(arr.length / 2);
  return arr.length % 2 ? arr[mid] : Math.round((arr[mid - 1] + arr[mid]) / 2);
}

let backlink_profile = null;

if (serp && targetCount && blResp && Array.isArray(blResp.tasks)) {
  const respItems = (blResp.tasks[0] && blResp.tasks[0].result) || [];
  if (Array.isArray(respItems) && respItems.length) {
    const byUrl = new Map();
    for (const it of respItems) {
      if (it && it.target) byUrl.set(String(it.target), it);
    }

    const perUrl = serp.organic.slice(0, 10).map(r => {
      const data = byUrl.get(r.url) || {};
      return {
        position: r.position,
        domain: r.domain,
        url: r.url,
        title: r.title,
        backlinks: typeof data.backlinks === 'number' ? data.backlinks : null,
        referring_domains: typeof data.referring_domains === 'number' ? data.referring_domains : null,
        referring_main_domains: typeof data.referring_main_domains === 'number' ? data.referring_main_domains : null,
        rank: typeof data.rank === 'number' ? data.rank : null
      };
    });

    const aggregates = {
      median_referring_domains: median(perUrl.map(p => p.referring_domains)),
      median_rank: median(perUrl.map(p => p.rank))
    };

    const ranked = perUrl.filter(p => typeof p.rank === 'number');
    if (ranked.length) {
      const weakest = ranked.reduce((min, cur) => (cur.rank < min.rank ? cur : min), ranked[0]);
      aggregates.weakest_position = weakest.position;
      aggregates.weakest_rank = weakest.rank;
    }

    backlink_profile = { per_url: perUrl, aggregates };
  }
}

// Strip transient fields, attach backlink_profile
const { bl_body, bl_target_count, ...rest } = upstream;
return [{ json: { ...rest, backlink_profile } }];

const upstream = $('Build LLM Payload').first().json;

// Surface KD + backlink_profile alongside the intent result, regardless of LLM outcome.
const kdFields = {
  keyword_difficulty: typeof upstream.keyword_difficulty === 'number' ? upstream.keyword_difficulty : null,
  difficulty_band: upstream.difficulty_band || null
};
const backlinkFields = { backlink_profile: upstream.backlink_profile || null };

if (upstream.intent_result && upstream.intent_result.error) {
  return [{ json: { intent_result: { ...upstream.intent_result, ...kdFields, ...backlinkFields } } }];
}

const response = $input.first().json;

if (response && response.error) {
  const errMsg = (response.error.message || response.error.code || JSON.stringify(response.error));
  return [{ json: { intent_result: { keyword: upstream.keyword, error: 'OpenRouter error: ' + errMsg, raw: response.error, ...kdFields, ...backlinkFields } } }];
}

const text = response &&
  response.choices &&
  response.choices[0] &&
  response.choices[0].message &&
  response.choices[0].message.content;

if (!text) {
  return [{ json: { intent_result: { keyword: upstream.keyword, error: 'No content in OpenRouter response', raw: response, ...kdFields, ...backlinkFields } } }];
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    parsed = JSON.parse(cleaned);
  } catch (e2) {
    return [{ json: { intent_result: { keyword: upstream.keyword, error: 'Failed to parse JSON from model', raw_text: text, ...kdFields, ...backlinkFields } } }];
  }
}

if (Array.isArray(parsed.sub_intents) && parsed.sub_intents.length) {
  const total = parsed.sub_intents.reduce((s, x) => s + (Number(x.weight) || 0), 0);
  if (total > 0 && Math.abs(total - 100) > 5) {
    parsed.sub_intents = parsed.sub_intents.map(x => ({
      label: x.label || '',
      weight: Math.round((Number(x.weight) || 0) * 100 / total)
    }));
  }
}

parsed.keyword = parsed.keyword || upstream.keyword;
Object.assign(parsed, kdFields, backlinkFields);

return [{ json: { intent_result: parsed } }];

const allItems = $input.all();
const inputs = $('Normalize Input').first().json;

const byKw = new Map();
for (const it of allItems) {
  const r = it.json && it.json.intent_result;
  if (r && r.keyword) byKw.set(r.keyword, r);
}

const results = inputs.keywords.map(kw =>
  byKw.get(kw) || { keyword: kw, error: 'No result returned from pipeline.' }
);

return [{
  json: {
    results,
    request: {
      keywords: inputs.keywords,
      location: inputs.location,
      language: inputs.language,
      device: inputs.device,
      industry: inputs.industry
    },
    generated_at: new Date().toISOString()
  }
}];
